{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C06"],
      "claim": "Maraviroc, a structurally similar basic-amine/amide heteroaromatic drug, has an absolute oral bioavailability of 23% in healthy volunteers at 100 mg, above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C59"],
      "claim": "Niraparib, which contains a basic piperidine and amide/heteroaromatic motifs similar to the query, has an absolute oral bioavailability of 72.7% measured against IV in cancer patients.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C38"],
      "claim": "Elinzanetant, a moderately sized amide-containing basic amine drug, has dose-independent oral bioavailability of 36.7%, supporting F ≥ 20% for this chemotype.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "KNI-272, a peptide-like molecule with thioether and amide functionalities, achieved 54.97% absolute oral bioavailability in fasting patients, indicating that such polar/large features do not preclude F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Pradigastat, despite a polar ionizable carboxylic acid and high aromatic surface, is completely bioavailable after oral administration, supporting high oral absorption for complex heteroaromatic drugs.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Multiple high-transfer experimental analogues with absolute oral bioavailability measurements consistently show F values from 23% to 73%, all above the 20% threshold. The most structurally relevant analogues—basic amine/amide heteroaromatics such as maraviroc, niraparib, and elinzanetant—support high bioavailability. The mixed physicochemical prior is outweighed by this consistent experimental evidence.",
  "evidence_gaps": [
    "No direct experimental oral bioavailability data for the query molecule.",
    "Food effect and formulation-dependent bioavailability are unknown for the query.",
    "Potential first-pass metabolism of the thioether or amide groups is not directly quantified.",
    "The fully ionized piperidine may affect permeability, but analogous basic drugs still achieve F ≥ 20%."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

